package site.kael.conversationcompiler.controller.settings;
import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import site.kael.conversationcompiler.domain.settings.*; import site.kael.conversationcompiler.service.settings.KnowledgeSettingsService; import java.util.*;
@RestController @RequestMapping("/api/v1/settings/knowledge") public class KnowledgeSettingsController { private final KnowledgeSettingsService service; public KnowledgeSettingsController(KnowledgeSettingsService s){service=s;} @GetMapping public ResponseEntity<KnowledgeCompileSettings> get(){return service.get().map(ResponseEntity::ok).orElseGet(()->ResponseEntity.noContent().build());} @PutMapping public ResponseEntity<Void> save(@RequestBody KnowledgeSettingsRequest r){service.save(r);return ResponseEntity.noContent().build();} @GetMapping("/model-options") public List<ModelOptions> options(){return service.options();} }
